#include "stdafx.h"

// =============================================================================
//  LocalizationPL.cpp  -- The Hell 4 -- Polish overlay  (th4)
//  LANG_PL = 7. Latin script, REAL CP1250 DIACRITICS.
//
//  ---- STATUS -------------------------------------------------------------
//  PL_Ui (883/883), PL_Menu (156/156) and the three PL_Trait* functions (111 each)
//  are COMPLETE. Every other table still
//  holds a lone placeholder row, so countRows() reports 0 and those categories
//  fall back to English. Fill them incrementally; nothing else has to change.
//
//  ---- ENCODING: READ THIS BEFORE TYPING A SINGLE POLISH WORD -------------
//  * Byte encoding is CP1250 (NOT CP1252 -- Polish is not a Western-European
//    codepage). Read/write this file in Python with encoding='cp1250'.
//    NEVER 'latin-1', NEVER 'utf-8'.
//  * Write the 9 Polish letters as \xNN escapes so the file itself stays ASCII:
//      A-ogonek \xA5   C-acute \xC6   E-ogonek \xCA   L-stroke \xA3
//      N-acute  \xD1   O-acute \xD3   S-acute \x8C   Z-acute \x8F   Z-dot \xAF
//      (lowercase: \xB9 \xE6 \xEA \xB3 \xF1 \xF3 \x9C \x9F \xBF)
//  * *** THE GREEDY-HEX C2022 TRAP APPLIES *** exactly as it does to RU/PT/FR.
//    A \x escape eats EVERY following ASCII hex digit, INCLUDING the letters
//    a-f / A-F. Polish is a heavy offender because hex letters follow diacritics
//    constantly: "\xA3AD" (L-stroke + A + D) fuses into \xA3AD -> C2022.
//    ALWAYS use the empty-string break:  "\xA3""ADNY"  not  "\xA3ADNY".
//    Scan every new line with regex  \\x[0-9A-Fa-f]{2}[0-9A-Fa-f]  -> must be 0 hits.
//  * The in-game CEL fonts (small/mid/big) are CAPS-ONLY, so lowercase CP1250
//    bytes alias the uppercase glyph. The ui_art menu atlas DOES have lowercase.
//  * Keys must byte-exactly match the English source literal: case, trailing
//    spaces, colons, and %i/%s/%u specifiers all preserved.
//
//  ---- FONTS -------------------------------------------------------------
//  All Polish glyph art ships in TH4loc_pol.mor (mounted at 8900 only when
//  language == PL, see Windows.cpp). It shadows the stock font filenames, so no
//  font loader has a Polish branch. Tables: Codepage_Polish / FontIndex*_Polish /
//  FontWidth{Mid,Big}_Polish in dataseg.cpp; FontWidthSmall[85..93] appended.
//  Known art compromises (13x11 small font is very tight): the ogoneks on
//  A-ogonek / E-ogonek are 2px nubs, and L-stroke's L is shifted right 2px.
//
//  English source is inviolable -- translate via these overlays only. Never edit
//  structs_speech.cpp / BaseQuests.cpp / English literals, and never touch the
//  RU/ID/PT/ES/IT/FR tables from this file.
// =============================================================================

struct UiStr  { const char* en; const char* pl; }; // .pl column holds the PL text
struct IdxStr { int index; const char* tr; };

enum {
	OVL_UI = 0, OVL_MENU, OVL_UNIQUE_ITEM, OVL_AFFIX_PREFIX, OVL_AFFIX_SUFFIX,
	OVL_BASE_ITEM, OVL_BASE_NAME2, OVL_ELEMENT, OVL_SPICIES, OVL_ICEAGE,
	OVL_SPELL, OVL_SPELL_NOM, OVL_PERK_NAME, OVL_PERK_DESC, OVL_WARP,
	// (th4) MUST stay in sync with the master enum in Localization.cpp -- the ids are
	// array indices shared across TUs. Appended last, so ids 0..14 are unchanged and the
	// other loc files need no edit: Localization.cpp loops to ITS OVL_STR_COUNT and
	// their GetStrTable() returns {0,0} for the unknown id, keeping the nominative.
	OVL_WARP_OBL,
	OVL_STR_COUNT
};
enum { OVL_SPEECH = 0, OVL_ONSCREEN, OVL_QUEST, OVL_IDX_COUNT };

