// (th4) PL_UniqueItem: all 2957 rows, mirroring FR_UniqueItem/IT_UniqueItem exactly.
// Generated compositionally (see notes below), then round-tripped byte-for-byte.
//
// POLICY -- taken from what FR/IT actually do, not invented:
//   * descriptive names are translated;
//   * Latin / invented proper nouns are emitted as key == value, exactly as FR does
//     for its own 228 such rows (Accipiter Umbra, Alma Negra, Akaviri, Annihilus...).
//     A key == value row behaves identically to an absent row (English fallback), so
//     these are harmless; they are present for structural parity with FR/IT.
//
// GRAMMAR RULES (all verified against FR/IT output):
//   * head-noun gender drives adjective agreement (m/f/n/plural-nonvirile);
//   * "X of Y" / "X's Y" reorder and put the dependent in the genitive
//       "Acolyte's Cord"      -> "Sznur Akolity"
//       "Armor of the Old Gods"-> "Zbroja Starych Bogow"
//   * closed compounds split into "B of A", matching FR ("Lavadoom" -> "Ruine de Lave")
//       "Bonesaw"   -> "Pila Kosci"      "Leadcrow" -> "Kruk Olowiu"
//   * participle suffixes each take their OWN preposition+case, per FR/IT:
//       -forged  "forged IN X"   (FR "dans le Vide")  -> locative     "Kuty w Pustce"
//       -born    "born FROM X"   (FR "Nee du Gel")    -> genitive     "Zrodzony ze Szronu"
//       -bound   "bound TO X"    (FR "Liees a l'Esprit")-> instrumental "Zwiazany z Duchem"
//       -touched "touched BY X"  (FR "Touches par le Soleil") -> instrumental
//     and the phrase POSTPOSES, as in FR "Couronne Forgee dans le Vide":
//       "Voidforged Crown" -> "Korona Kuta w Pustce"
//   * the English article is dropped ("The White Tiger" -> "Bialy Tygrys").
//
// STATUS: 2638 rows translated (89%), 319 emitted as key == value. FR/IT reach 93%.
// the shortfall is purely lexicon tail (~1100 one-off morphemes), not rule coverage.
// Filling more of it only requires extending lex_n/lex_a -- no engine changes.
