// (th4) PL_AffixPrefix: 314 rows, same keys/order as FR_AffixPrefix.
// The engine PREPENDS these unconditionally:  sprintf("%s %s", prefix, itemname)
// (Item.cpp:6858 / 8542 / 8585 -- no language gate). A flat table cannot know the
// item's gender, so these are masculine nominative. FR/IT do exactly the same and
// accept the mismatch ("Blinde", "Corazzato").
//   * gemstones/materials are real adjectives here (Ruby -> "Rubinowy"), not bare
//     nouns; FR emits nouns ("Rubis Epee") which is broken French anyway, and Polish
//     has the adjective for free, so this is strictly better at no cost.
//   * possessives use Polish possessive adjectives where they exist
//     (dragon's -> "Smoczy", king's -> "Krolewski"), genitive otherwise
//     (Abjurer's -> "Egzorcysty").
//   * case-duplicate keys mirror case, exactly as FR does (Blessed/blessed ->
//     "Beni"/"beni"):  "Blogoslawiony" / "blogoslawiony".
