// (th4) PL_AffixSuffix: 358 rows, same keys/order as FR_AffixSuffix.
// The engine appends via a LOCALIZED connector:
//     sprintf(L("%s of %s"), itemname, suffix)          (Item.cpp:8572 / 8588)
// PL_Ui maps "%s of %s" -> "%s %s" (bare juxtaposition), because Polish marks this
// relation with CASE, not a preposition. Every value below is therefore GENITIVE:
//     "Miecz" + " " + "Rozgrzeszenia"  ->  "Miecz Rozgrzeszenia"
// This is the one place PL diverges structurally from FR: FR keeps the nominative
// ("Absolution") because its connector "%s de %s" carries the relation.
// English articles are dropped ("the Stars" -> "Gwiazd", cf. FR "les Etoiles").
