// Base item names. Item.cpp:6287/6288 -> item.Name / FullMagicalItemName.
// Composed with gender agreement: Polish adjectives must match the head noun, so
// these were generated from a noun lexicon (gender-tagged, shared with PL_BaseName2)
// plus a modifier lexicon storing each adjective as stem+declension class. All four
// gender forms are DERIVED, so "Leather" is one entry yielding Skorzana Zbroja (f) /
// Skorzane Rekawice (p) / Skorzany Kaftan (m) -- agreement cannot drift row to row.
// Roman numerals kept; "(grade N)" -> "(stopien N)"; model codes (M134, T-51b, UZI)
// verbatim, as in FR.
//
// The 34 "Relict of X" rows reuse the PL_Spell GENITIVE verbatim, so the two tables
// cannot disagree ("Relict of Fire Wall" -> "Relikwia Sciany Ognia").
//
// INVARIANT: every "Relict of X" row renders as "Relikwia X" -- 8 bytes, pure ASCII.
// Item.cpp's classic-mode Relict->Scroll swap needs a LANG_PL branch matching those
// 8 bytes and rebuilding as "Zwoj" (4 bytes, o-acute) -- lengths differ, so it must
// rebuild like the ID/PT/ES/IT/FR branches, NOT memcpy in place. THAT BRANCH DOES NOT
// EXIST YET: PL currently falls through to the else, which memcmp's "Relict" and
// never matches, so the rename silently no-ops for Polish.
