// Polish "do" governs the genitive, so the nominative PL_Warp rows would render
// "Do Miasto" / "Do Komnata Kosci". Same problem Russian has ("V" + accusative);
// FR/IT/ES escape it only because "Vers"/"A" do not inflect.
