// -----------------------------------------------------------------------------
//  Getters consumed by InitLanguageOverlays() in Localization.cpp.
// -----------------------------------------------------------------------------
static bool isPlaceholder( const UiStr&  r ) { return r.en == 0; }
static bool isPlaceholder( const IdxStr& r ) { return r.index < 0 && r.tr == 0; }

template<typename T, size_t N>
static int countRows( const T (&arr)[N] )
{
	if( N == 1 && isPlaceholder( arr[0] ) ) return 0;
	return (int)N;
}

// =============================================================================
//  GameChanger InfoWindow text. Wired via LocalizedGCInfoName/Desc in
//  Localization.cpp. Translated from the English master in GameChangers.cpp
//  (GC_Names_InfoWindow / GC_Descriptions_InfoWindow), not from FR.
//  The "\n" escapes are load-bearing (blank-line layout in the panel); counts
//  match the English exactly. GC 27/28/29 are Terminator/Fallout crossovers --
//  proper nouns kept verbatim.
// =============================================================================
const char* PL_GCInfoName( int gc )
{
	switch( gc ){
		case 0: return "Brak (pomini\xEAte)";
		case 1: return "Autozapis";
		case 2: return "Zwi\xB9zany Ekwipunek";
		case 3: return "Wypadanie Przedmiot\xF3w";
		case 4: return "Bez Wysi\xB3ku";
		case 5: return "\xAFycie z Ziemi";
		case 6: return "Niemo\xBFliwe";
		case 7: return "Prohibicja";
		case 8: return "Pe\xB3ny Kontakt";
		case 9: return "Nocni Pobratymcy";
		case 10: return "R\xB9""b i Siecz";
		case 11: return "Zaszczepiony";
		case 12: return "To M\xF3j Sekret";
		case 13: return "Brak Regeneracji";
		case 14: return "Czyste R\xEA""ce";
		case 15: return "Epoka Lodowcowa";
		case 16: return "Dzie\xF1 \x8Cwistaka";
		case 17: return "Twardsze Potwory";
		case 18: return "Niezniszczalne Przedmioty";
		case 19: return "Brak Mapy";
		case 20: return "Podw\xF3jne Obra\xBF""enia";
		case 21: return "Nie Widz\xEA Z\xB3""a";
		case 22: return "Czarna \x8Cmier\xE6";
		case 23: return "Pech";
		case 24: return "Bezlitosne \xAF""elazo";
		case 25: return "Przyspieszenie";
		case 26: return "Asceza";
		case 27: return "Terminator";
		case 28: return "Supermutant";
		case 29: return "\xAFo\xB3nierz Enklawy";
		default: return nullptr;
	}
}

const char* PL_GCInfoDesc( int gc )
{
	switch( gc ){
		case 0: return "Brak (pomini\xEAte)";
		case 1: return "Autozapis\n\n\nZmienia styl gry\n\nUsuwa konieczno\x9C\xE6 r\xEA""cznego zapisywania gry przez gracza, zapis odbywa si\xEA automatycznie, tak jak w trybie wieloosobowym.";
		case 2: return "Zwi\xB9zany Ekwipunek\n\n\nDodaje wyzwanie\n\nUniemo\xBFliwia zak\xB3""adanie i zdejmowanie przedmiot\xF3w w walce (poza slotami r\xB9k).";
		case 3: return "Wypadanie Przedmiot\xF3w\n\n\nDodaje wyzwanie\n\n\x8Cmier\xE6 powoduje wypadni\xEA""cie za\xB3o\xBFonych przedmiot\xF3w.\n\nUwaga: je\x9Cli wypadni\xEAte przedmioty nie zostan\xB9 odzyskane w tej samej sesji gry, znikn\xB9.";
		case 4: return "Bez Wysi\xB3ku\n\n\nU\xB3""atwia gr\xEA\n\nPotwory zadaj\xB9 ci tylko po\xB3ow\xEA obra\xBF""e\xF1.\n\xA3""atwiej ju\xBF si\xEA nie da.";
		case 5: return "\xAFycie z Ziemi\n\n\nDodaje wyzwanie\n\nMieszczanie nie sprzedadz\xB9 ci \xBF""adnych przedmiot\xF3w.\n\nNie przestan\xB9 jednak \x9Cwiadczy\xE6 swoich us\xB3ug: plotki, dialogi zada\xF1, naprawa, identyfikacja, zaklinanie, wytwarzanie, osadzanie, \xB3""adowanie.";
		case 6: return "Niemo\xBFliwe\n\n\nUtrudnia gr\xEA\n\nPotwory zadaj\xB9 ci podw\xF3jne obra\xBF""enia.\nTrudniej ju\xBF si\xEA nie da.";
		case 7: return "Prohibicja\n\n\nDodaje wyzwanie\n\nPotwory nie b\xEA""d\xB9 ju\xBF losowo upuszcza\xE6 eliksir\xF3w cech\nUwaga: perk Zapalony Pijak wci\xB9\xBF b\xEA""dzie dawa\xB3 eliksiry z unikatowych potwor\xF3w";
		case 8: return "Pe\xB3ny Kontakt\n\n\nU\xB3""atwia gr\xEA\n\nPotwory z atakami dystansowymi nie wycofuj\xB9 si\xEA.";
		case 9: return "Nocni Pobratymcy\n\n\nCzyni ci\xEA wampirem\n\n\xAFyjesz i umierasz przez krew. tw\xF3j g\xB3\xF3""d jest nienasycony, lecz masz wszystkie narz\xEA""dzia, by polowa\xE6 na s\xB3""abych\n\nTo zmienia rozgrywk\xEA.\nNie u\xBFywasz przedmiot\xF3w i polegasz na swych wrodzonych mocach.";
		case 10: return "R\xB9""b i Siecz\n\n\nU\xB3""atwia gr\xEA\n\nNie musisz ju\xBF zmienia\xE6 typu broni (ostrej lub obuchowej), by dostosowa\xE6 si\xEA do typu potwora. Wszystkie bronie zadaj\xB9 standardowe obra\xBF""enia wszystkim gatunkom potwor\xF3w.";
		case 11: return "Zaszczepiony\n\n\nU\xB3""atwia gr\xEA\n\nPotwory trac\xB9 wszystkie odporno\x9C""ci i nie ma potrzeby zmieniania zakl\xEA\xE6 - dzia\xB3""a ka\xBF""dy typ zakl\xEA""cia.\nKamienna Kl\xB9twa, Kostny Duch oraz zakl\xEA""cia \xAFywio\xB3\xF3w i \x8Cwi\xEAte pozostaj\xB9 bez zmian.";
		case 12: return "To M\xF3j Sekret\n\n\nU\xB3""atwia gr\xEA\n\nFuria nie ma odnowienia i mo\xBFna j\xB9 rzuci\xE6 ponownie, gdy tylko si\xEA sko\xF1""czy.";
		case 13: return "Brak Regeneracji\n\n\nDodaje wyzwanie\n\nPosta\xE6 nie ma podstawowej regeneracji \xBFycia i many.";
		case 14: return "Czyste R\xEA""ce\n\n\nDodaje wyzwanie\n\nPotwory nie upuszczaj\xB9 przedmiot\xF3w, kt\xF3re posta\xE6 mo\xBF""e za\xB3o\xBFy\xE6.\nGracz ma je zdobywa\xE6 poprzez kupno i/lub zaklinanie.";
		case 15: return "Epoka Lodowcowa\n\n\nZmiana kosmetyczna\n\nPoziomy loch\xF3w wygl\xB9""daj\xB9 jak w g\xB3\xEA""bokiej, g\xB3\xEA""bokiej zimie, wszystko jest oblodzone i zamarzni\xEAte.\nCzy wyobra\xBF""a\xB3""e\x9C sobie kiedy\x9C, jak wygl\xB9""da\xB3oby Piek\xB3o, gdyby zamarz\xB3o?";
		case 16: return "Dzie\xF1 \x8Cwistaka\n\n\nZmienia styl gry\n\nZa ka\xBF""dym razem generowany jest ten sam loch, zaludniony tymi samymi potworami. Mo\xBF""esz gra\xE6 i poprawia\xE6 swoje tempo przy ka\xBF""dej rozgrywce.";
		case 17: return "Twardsze Potwory\n\n\nUtrudnia gr\xEA\n\nPotwory maj\xB9 +200% punkt\xF3w \xBFycia.";
		case 18: return "Niezniszczalne Przedmioty\n\n\nU\xB3""atwia gr\xEA\n\nPrzedmioty nie zostan\xB9 zniszczone, gdy wytrzyma\xB3o\x9C\xE6 spadnie do zera. Zamiast tego stan\xB9 si\xEA bezu\xBFyteczne do czasu naprawy.";
		case 19: return "Brak Mapy\n\n\nDodaje wyzwanie\n\nAutomapa jest niedost\xEApna\nB\xEA""dziesz musia\xB3 odnajdywa\xE6 drog\xEA w lochach bez polegania na niej\n\nJu\xBF czujesz si\xEA zagubiony?";
		case 20: return "Podw\xF3jne Obra\xBF""enia\n\n\nU\xB3""atwia gr\xEA\n\nTwoje ataki zadaj\xB9 potworom podw\xF3jne obra\xBF""enia\n\nUwaga: mo\xBF""e sta\xE6 si\xEA rozczarowuj\xB9""co \xB3""atwo.\nNie wybieraj tego, je\x9Cli chcesz zachowa\xE6 dreszcz walki.";
		case 21: return "Nie Widz\xEA Z\xB3""a\n\n\nDodaje wyzwanie\n\nWidzenie nie pod\x9Cwietla potwor\xF3w w ciemno\x9C""ci.";
		case 22: return "Czarna \x8Cmier\xE6\n\n\nJeste\x9C zara\xBFony\n\nZaraza Czarnej \x8Cmierci opanowa\xB3""a ci\xEA. B\xEA""dzie powoli rozwija\xE6 niekorzystne objawy, kt\xF3re ostatecznie nieuchronnie ci\xEA zabij\xB9.\n\nNie mo\xBF""esz jej wyleczy\xE6, nie mo\xBF""esz jej uzdrowi\xE6 i nie mo\xBF""esz jej powstrzyma\xE6. Z czasem b\xEA""dzie coraz ci\xEA\xBFsza. Nie ma ucieczki przed t\xB9 \x9Cmierteln\xB9 chorob\xB9.";
		case 23: return "Pech\n\n\nDodaje wyzwanie\n\nSzcz\xEA\x9C""cie pr\xEA""dzej czy p\xF3\x9Fniej si\xEA ko\xF1""czy. Twoje nawet si\xEA nie zacz\xEA\xB3o.\n\nZaczynasz gr\xEA ze wszystkimi cechami r\xF3wnymi 5. Otrzymujesz tylko 2 punkty cech na poziom. Umiej\xEAtno\x9C""ci znajdowania magii, zdobywane do\x9Cwiadczenie i zdolno\x9C\xE6 znajdowania z\xB3ota zmniejszone o 75%. Zaczynasz gr\xEA bez \xBF""adnych przedmiot\xF3w.\n\n\xAF""adnych perk\xF3w, kt\xF3re pomog\xB3yby ci z do\x9Cwiadczeniem, eliksirami, znajdowaniem magicznych przedmiot\xF3w i cechami na poziom.";
		case 24: return "Bezlitosne \xAF""elazo\n\n\nDodaje wyzwanie\n\nKlasyczny Ironman w Diablo by\xB3 inny.\n\nNie by\xB3o premii do cech za poziom, dodatkowego do\x9Cwiadczenia, olej\xF3w ani identyfikacji od boss\xF3w. Nie by\xB3o te\xBF poprawy znajdowania magii.\n\nTen GC cofa ci\xEA do tych korzeni.";
		case 25: return "Przyspieszenie\n\n\nU\xB3""atwia gr\xEA\n\nDo\x9Cwiadczenie zwi\xEAkszone 2x.";
		case 26: return "Asceza\n\n\nDodaje wyzwanie\n\nGra jest zapisywana automatycznie.\n\nPrzedmioty wypadaj\xB9 po \x9Cmierci. Nie mo\xBF""esz wskrzesi\xE6 si\xEA w mie\x9C""cie (musisz stworzy\xE6 now\xB9 gr\xEA), przez co wszystkie wypadni\xEAte przedmioty s\xB9 stracone.\n\nTo jak tryb Hardcore, ale zamiast traci\xE6 posta\xE6, tracisz za\xB3o\xBFone przedmioty.";
		case 27: return "Terminator\n\n\nJeste\x9C jednostk\xB9 serii Cyberdyne Systems. Model 101, infiltrator. Tryb odczytu-zapisu CPU aktywowany. Wys\xB3""any w przesz\xB3o\x9C\xE6, by wykona\xE6 misj\xEA.\n\nCel g\xB3\xF3wny: Uber Diablo.\n\nCel drugorz\xEA""dny: eksterminacja potwor\xF3w.\n\nWarunek: wydawa\xE6 si\xEA cz\xB3owiekiem miejscowym podmiotom.\n\nPodstawowe ulepszenia zainstalowane. Dodatkowe ulepszenia dost\xEApne poprzez samouczenie.";
		case 28: return "Supermutant\n\n\nTwoja postura ud\x9Fwignie bronie, kt\xF3re prze\xB3""ama\xB3yby zwyk\xB3""ego cz\xB3owieka na p\xF3\xB3.\n\nMiniguny.\n\nRzeczy, kt\xF3re nie powinny istnie\xE6 na tym \x9Cwiecie. Nie rzucasz ju\xBF zakl\xEA\xE6. Nie musisz.\n\nGdy poci\xB9gasz za spust, seria rozdziera piekielny pomiot jak papier na wietrze.";
		case 29: return "\xAFo\xB3nierz Enklawy\n\n\n\xAFo\xB3nierz Si\xB3 Zbrojnych Enklawy, wyszkolony do eksterminacji mutant\xF3w i genetycznej nieczysto\x9C""ci.\n\nTrafia do \x9Cwiata, kt\xF3ry nigdy nie zazna\xB3 ognia nuklearnego, lecz ma plugastwo innego rodzaju - Piekielny Pomiot.\n\nWr\xF3g si\xEA zmieni\xB3. Cel nie.\n\nZdolno\x9C""ci: w\xB3""ada broni\xB9 energetyczn\xB9 i rozstawia drony bojowe. Bieg\xB3y w walce \xBFywio\xB3""ami.";
		default: return nullptr;
	}
}

