//  Base monster names (NOMINATIVE -- shown bare on the hover/health bar).
//  English master: BaseMonster.cpp, name field of each row (incl. the CLASSIC block).
//  387 ids over 311 distinct names -- duplicates are intentional (e.g. the classic
//  BM_C_* rows reuse the same creature names as their modern counterparts).
//  Policy mirrors FR/PL_IceAge: descriptive names translate, opaque coinages and
//  proper nouns stay verbatim (Balrog, Izual, Hephasto, Pinky, Uber Diablo...).
//  "Adept" is the correct Polish word and is identical to the English by coincidence.
