const UiStr* PL_GetStrTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_UI:                *n = countRows(PL_Ui);          return PL_Ui;
		case OVL_MENU:              *n = countRows(PL_Menu);        return PL_Menu;
		case OVL_UNIQUE_ITEM:       *n = countRows(PL_UniqueItem);  return PL_UniqueItem;
		case OVL_AFFIX_PREFIX:      *n = countRows(PL_AffixPrefix); return PL_AffixPrefix;
		case OVL_AFFIX_SUFFIX:      *n = countRows(PL_AffixSuffix); return PL_AffixSuffix;
		case OVL_BASE_ITEM:         *n = countRows(PL_BaseItem);    return PL_BaseItem;
		case OVL_BASE_NAME2:        *n = countRows(PL_BaseName2);   return PL_BaseName2;
		case OVL_ELEMENT:           *n = countRows(PL_Element);     return PL_Element;
		case OVL_SPICIES:           *n = countRows(PL_Spicies);     return PL_Spicies;
		case OVL_ICEAGE:            *n = countRows(PL_IceAge);      return PL_IceAge;
		case OVL_SPELL:             *n = countRows(PL_Spell);       return PL_Spell;
		case OVL_SPELL_NOM:         *n = countRows(PL_SpellNom);    return PL_SpellNom;
		case OVL_PERK_NAME:         *n = countRows(PL_PerkName);    return PL_PerkName;
		case OVL_PERK_DESC:         *n = countRows(PL_PerkDesc);    return PL_PerkDesc;
		case OVL_WARP:              *n = countRows(PL_Warp);        return PL_Warp;
		case OVL_WARP_OBL:          *n = countRows(PL_WarpOblique); return PL_WarpOblique;
	}
	*n = 0; return 0;
}

const IdxStr* PL_GetIdxTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_SPEECH:        *n = countRows(PL_Speech);   return PL_Speech;
		case OVL_ONSCREEN:      *n = countRows(PL_OnScreen); return PL_OnScreen;
		case OVL_QUEST:         *n = countRows(PL_Quest);    return PL_Quest;
	}
	*n = 0; return 0;
}


// ============================================================================
// (th4) Polish dedicated per-language functions (LANG_PL). Mirror the ES_*/IT_*/
// FR_* functions. Dispatched from Traits.cpp via parallel `GameLanguage ==
// LANG_PL` branches. REAL CP1250 diacritics -- the in-game CEL fonts ship in
// TH4loc_pol.mor. Formula tokens (CLVL, MAG, DEX, ^, %, /) are left verbatim;
// only prose is translated. ODE = "obrazenia od wrogow" (the DFE acronym, kept
// consistent with PL_Ui). Returns 0 for an unknown id => English fallback.
// ============================================================================

